import{_ as n,o as t,c as a,a2 as r}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Router und Parallel","description":"Den Ablauf eines Flows verzweigen, wiederholen und verzögern.","frontmatter":{"title":"Router und Parallel","description":"Den Ablauf eines Flows verzweigen, wiederholen und verzögern."},"headers":[],"relativePath":"flows/router-und-parallel.md","filePath":"flows/router-und-parallel.md","lastUpdated":1786174778000}'),i={name:"flows/router-und-parallel.md"};function s(l,e,d,u,h,o){return t(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="router-parallel-und-warten" tabindex="-1">Router, Parallel und Warten <a class="header-anchor" href="#router-parallel-und-warten" aria-label="Permalink to &quot;Router, Parallel und Warten&quot;">​</a></h1><p>Die vier <strong>Helfer</strong> steuern den Ablauf eines Flows, statt selbst etwas zu tun. Sie liegen im Editor im Reiter <strong>Helfer</strong>.</p><table tabindex="0"><thead><tr><th>Helfer</th><th>Beschreibung in der Oberfläche</th></tr></thead><tbody><tr><td><strong>Router</strong></td><td><em>Verschiedene Wege gehen</em></td></tr><tr><td><strong>Parallel</strong></td><td><em>Führt nachfolgende Schritte für jedes Listenelement einzeln aus.</em></td></tr><tr><td><strong>Durchläufe zusammenführen</strong></td><td><em>Wartet auf alle Listendurchläufe und führt den Flow anschließend fort.</em></td></tr><tr><td><strong>Warten</strong></td><td><em>Pausiert den Flow für eine festgelegte Dauer.</em></td></tr></tbody></table><hr><h2 id="router" tabindex="-1">Router <a class="header-anchor" href="#router" aria-label="Permalink to &quot;Router&quot;">​</a></h2><p>Der Router verzweigt den Flow: Je nach Bedingung geht es einen anderen Weg weiter.</p><p><strong>Typische Anwendungen:</strong></p><ul><li>Nach Betrag: über 1000 € zur Freigabe, darunter direkt bestätigen</li><li>Nach Kategorie: Anfrage an das jeweils zuständige Team</li><li>Nach Status: unterschiedliche Benachrichtigungen</li></ul><h3 id="bedingungen" tabindex="-1">Bedingungen <a class="header-anchor" href="#bedingungen" aria-label="Permalink to &quot;Bedingungen&quot;">​</a></h3><p>An jedem ausgehenden Weg legen Sie eine Bedingung fest. Zur Verfügung stehen:</p><table tabindex="0"><thead><tr><th>Operator</th><th></th></tr></thead><tbody><tr><td><em>ist gleich</em></td><td><em>ist nicht gleich</em></td></tr><tr><td><em>ist größer als</em></td><td><em>ist kleiner als</em></td></tr><tr><td><em>ist größer als oder gleich</em></td><td><em>ist kleiner als oder gleich</em></td></tr><tr><td><em>beginnt mit</em></td><td><em>endet mit</em></td></tr><tr><td><em>enthält</em></td><td></td></tr><tr><td><em>ist vor</em></td><td><em>ist nach</em></td></tr><tr><td><em>ist leer</em></td><td><em>ist nicht leer</em></td></tr><tr><td><em>ist wahr</em></td><td><em>ist falsch</em></td></tr></tbody></table><p>Mehrere Bedingungen verknüpfen Sie mit <strong>und</strong> beziehungsweise <strong>oder</strong>.</p><p>Die Werte holen Sie aus vorherigen Schritten — siehe <a href="/docs/flows/daten-zwischen-schritten">Daten zwischen Schritten</a>.</p><div class="tip custom-block"><p class="custom-block-title">Immer einen Standardweg vorsehen</p><p>Trifft keine Bedingung zu, läuft der Flow an dieser Stelle ins Leere. Bei Zahlen und Auswahlfeldern denkt man leicht nur an die erwarteten Fälle und vergisst leere Werte.</p><p>Sehen Sie einen Weg mit <em>ist leer</em> vor oder formulieren Sie die letzte Bedingung so, dass sie alles Übrige auffängt.</p></div><div class="warning custom-block"><p class="custom-block-title">Bedingungen prüfen, bevor der Flow produktiv geht</p><p>Ein Router mit falsch gesetzter Bedingung schickt Vorgänge stillschweigend in den falschen Zweig — es gibt keine Fehlermeldung. Testen Sie jeden Zweig einzeln mit passenden Testdaten. → <a href="/docs/flows/testen">Flows testen</a></p></div><hr><h2 id="parallel" tabindex="-1">Parallel <a class="header-anchor" href="#parallel" aria-label="Permalink to &quot;Parallel&quot;">​</a></h2><p><strong>Parallel</strong> ist die Schleife: Der Schritt nimmt eine <strong>Liste</strong> und führt die nachfolgenden Schritte <strong>für jedes Element einzeln</strong> aus.</p><p>Fast immer steht davor ein Schritt, der eine Liste liefert:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Auslöser</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Alle Einträge laden          →  liefert eine Liste</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Parallel                     →  je Element einmal</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>E-Mail                       →  läuft je Eintrag</span></span></code></pre></div><p><strong>Typische Anwendungen:</strong></p><ul><li>Serienmail an alle Einträge einer Ansicht</li><li>Je Position einer Rechnung einen Vorgang anlegen</li><li>Zeilen einer importierten CSV-Datei einzeln verarbeiten</li></ul><div class="tip custom-block"><p class="custom-block-title">Ohne Parallel passiert es nur einmal</p><p>Der häufigste Fehler beim Arbeiten mit Listen: <em>Alle Einträge laden</em> verwenden und sich wundern, dass die folgende E-Mail nur einmal verschickt wird — oder mit unbrauchbarem Inhalt.</p><p>Eine Liste ist noch keine Wiederholung. Erst <strong>Parallel</strong> macht daraus einzelne Durchläufe.</p></div><div class="warning custom-block"><p class="custom-block-title">Bei großen Listen aufpassen</p><p>Läuft <em>Parallel</em> über eine ungefilterte Ansicht mit tausenden Einträgen, werden die folgenden Schritte tausendfach ausgeführt — inklusive E-Mails und Aufrufen fremder Systeme.</p><p>Filtern Sie die Ansicht vorher auf das, was wirklich verarbeitet werden soll, und testen Sie mit einer kleinen Menge.</p></div><hr><h2 id="durchlaufe-zusammenfuhren" tabindex="-1">Durchläufe zusammenführen <a class="header-anchor" href="#durchlaufe-zusammenfuhren" aria-label="Permalink to &quot;Durchläufe zusammenführen&quot;">​</a></h2><blockquote><p><em>Wartet auf alle Listendurchläufe und führt den Flow anschließend fort.</em></p></blockquote><p><strong>Parallel</strong> öffnet einen Bereich, in dem die folgenden Schritte je Listenelement einzeln laufen. <strong>Durchläufe zusammenführen</strong> schließt diesen Bereich wieder: Der Flow wartet, bis <strong>alle</strong> Durchläufe fertig sind, und läuft danach ein einziges Mal weiter.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Alle Einträge laden          →  Liste</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Parallel                     →  ab hier je Element einzeln</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>E-Mail                       →  läuft je Eintrag</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Durchläufe zusammenführen    →  wartet auf alle</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Eintrag aktualisieren        →  läuft wieder nur einmal</span></span></code></pre></div><p>Der Schritt hat <strong>keine Einstellungen</strong> — er markiert nur das Ende des parallelen Bereichs.</p><div class="tip custom-block"><p class="custom-block-title">Wofür Sie ihn brauchen</p><p>Ohne diesen Schritt bleibt alles nach <em>Parallel</em> im Wiederholungsmodus. Sobald Sie nach der Schleife etwas <strong>einmalig</strong> tun wollen, brauchen Sie ihn:</p><ul><li>eine Zusammenfassung verschicken, nachdem alle Einzelmails raus sind</li><li>einen Sammelstatus setzen, nachdem alle Positionen verarbeitet wurden</li><li>den Vorgang abschließen, wenn alle Zeilen eines Imports durch sind</li></ul></div><div class="tip custom-block"><p class="custom-block-title">Verschachtelung ist möglich</p><p>Jedes <em>Parallel</em> öffnet eine Ebene, jedes <em>Durchläufe zusammenführen</em> schließt eine. Damit lassen sich Schleifen ineinander verschachteln — etwa je Rechnung über deren Positionen.</p><p>Achten Sie darauf, dass die Paare zusammenpassen. Ein fehlendes Zusammenführen lässt den Flow im Wiederholungsmodus, ein überzähliges hat nichts zu schließen.</p></div><hr><h2 id="warten" tabindex="-1">Warten <a class="header-anchor" href="#warten" aria-label="Permalink to &quot;Warten&quot;">​</a></h2><p><strong>Warten</strong> pausiert den Flow für eine festgelegte Dauer und setzt ihn danach fort.</p><p><strong>Typische Anwendungen:</strong></p><ul><li>Erinnerung einige Tage nach einer Anmeldung</li><li>Nachfassen, wenn nach einer Frist keine Rückmeldung kam</li><li>Abstand zwischen zwei Aufrufen eines fremden Systems</li></ul><div class="tip custom-block"><p class="custom-block-title">Warten ist keine Terminplanung</p><p><em>Warten</em> misst ab dem Zeitpunkt, an dem der Schritt erreicht wird — nicht bis zu einem festen Datum. „Drei Tage nach dem Auslöser&quot; geht damit gut; „jeden Montag um 9 Uhr&quot; nicht.</p></div><p>Ein wartender Durchlauf hat in der <a href="/docs/flows/durchlaufhistorie">Durchlaufhistorie</a> den Status <strong>Wartet</strong>.</p><hr><h2 id="zusammenfuhren-liste-ja-router-nein" tabindex="-1">Zusammenführen: Liste ja, Router nein <a class="header-anchor" href="#zusammenfuhren-liste-ja-router-nein" aria-label="Permalink to &quot;Zusammenführen: Liste ja, Router nein&quot;">​</a></h2><p>Die beiden Verzweigungsarten verhalten sich unterschiedlich:</p><table tabindex="0"><thead><tr><th></th><th>Wird wieder zusammengeführt</th></tr></thead><tbody><tr><td><strong>Parallel</strong> — Wiederholung über eine Liste</td><td><strong>ja</strong>, über <em>Durchläufe zusammenführen</em></td></tr><tr><td><strong>Router</strong> — Verzweigung nach Bedingungen</td><td><strong>nein</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Router-Zweige laufen getrennt zu Ende</p><p>Für den Router gibt es keinen Zusammenführungsschritt. Bauen Sie Abläufe deshalb so, dass jeder Zweig für sich endet.</p><p>Braucht es an mehreren Zweigenden dasselbe, legen Sie den Schritt in jedem Zweig an. <em>Durchläufe zusammenführen</em> hilft hier nicht — er schließt einen <strong>Parallel</strong>-Bereich, keine Router-Verzweigung.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/flows/aktionen">Aktionen</a></li><li><a href="/docs/flows/daten-zwischen-schritten">Daten zwischen Schritten</a></li><li><a href="/docs/flows/testen">Flows testen</a></li></ul>`,46)])])}const m=n(i,[["render",s]]);export{g as __pageData,m as default};
